const j=$json||{};
return [{json:{
  run_id:'RC-'+String(Date.now()).slice(-6),
  period:j.period||j.Period||'2026-09',
  materiality:Number(j.materiality||j.Materiality||50),
  source_label:j.source_label||j['Source system']||'Accounting export vs bank source',
  started_at:new Date().toISOString().slice(0,19)+'Z',
  status:'running',
}}];

const run=$('Prepare Run').first().json.run_id;
const today=new Date(); const d=(offset)=>{const x=new Date(today);x.setDate(x.getDate()-offset);return x.toISOString().slice(0,10);};
const amount=(i)=>100+i*10;
const counterparty=(i)=>['Northline','Kestrel','Halden','Juniper','Pine'][i%5];
const ledger=[]; const source=[];
for(let i=1;i<=40;i++){
  const ref='INV-'+(1000+i);
  const base={ref,period:'2026-09',date:d(1),currency:'CAD',counterparty:counterparty(i)};
  const a=amount(i).toFixed(2);
  if(i!==1012-1000){ /* keep 1012 out of source */ }
  ledger.push({...base,kind:'ledger',amount:a});
  if(i!==12) source.push({...base,kind:'source',amount:a,source_date:d(1)});
}
// seeded defects
ledger.push({...ledger[4],kind:'ledger',amount:amount(5).toFixed(2)}); // duplicate INV-1005 (row 5)
source.find(r=>r.ref==='INV-1018').amount=(amount(18)-12).toFixed(2); // mismatch 12.00
source.find(r=>r.ref==='INV-1027').source_date=d(9); // stale sync
source.push({kind:'source',ref:'INV-1099',period:'2026-09',date:d(1),currency:'CAD',counterparty:'Onix',amount:'2450.00',source_date:d(1)}); // missing in ledger
return [...ledger,...source].map((r)=>({json:{...r,run_id:run}}));

const items=$input.all().map((i)=>i.json);
const run=$('Prepare Run').first().json;
const TOLERANCE=0.5, STALE_DAYS=3;
const ledger=items.filter((r)=>r.kind==='ledger');
const source=items.filter((r)=>r.kind==='source');
const ledgerBy={}; const dupRefs=new Set();
for(const r of ledger){ if(ledgerBy[r.ref]) dupRefs.add(r.ref); ledgerBy[r.ref]=r; }
const sourceBy={}; for(const r of source) sourceBy[r.ref]=r;
const findings=[]; const add=(type,ref,severity,impact,detail,side)=>findings.push({type,ref,severity,amount_impact:Number(impact||0),detail,side});
for(const ref of dupRefs) add('duplicate_ledger',ref,'high',0,'reference appears more than once in the ledger','ledger');
const ledgerRefs=Object.keys(ledgerBy); const sourceRefs=Object.keys(sourceBy);
const matchedRefs=ledgerRefs.filter((r)=>sourceBy[r]);
for(const ref of ledgerRefs){ if(!sourceBy[ref]) add('missing_in_source',ref,'high',Number(ledgerBy[ref].amount),'in ledger, absent from source export','ledger'); }
for(const ref of sourceRefs){ if(!ledgerBy[ref]) add('missing_in_ledger',ref,'high',Number(sourceBy[ref].amount),'in source export, absent from ledger','source'); }
for(const ref of matchedRefs){
  const l=ledgerBy[ref], s=sourceBy[ref];
  const la=Number(l.amount), sa=Number(s.amount);
  if(Math.abs(la-sa)>TOLERANCE) add('amount_mismatch',ref,'high',Math.abs(la-sa),'ledger '+la.toFixed(2)+' vs source '+sa.toFixed(2),'both');
  if((la>0&&sa<0)||(la<0&&sa>0)) add('sign_error',ref,'high',Math.abs(la-sa),'sign differs between ledger and source','both');
  const stale=Math.round((new Date(run.started_at.slice(0,10))-new Date(s.source_date))/864e5);
  if(!isNaN(stale)&&stale>STALE_DAYS) add('stale_source',ref,'medium',0,'source date '+stale+' days older than the run','source');
}
const variance=findings.reduce((sum,f)=>sum+f.amount_impact,0);
const byType=findings.reduce((a,f)=>{a[f.type]=(a[f.type]||0)+1;return a;},{});
const summary={
  run_id:run.run_id, period:run.period, materiality:run.materiality,
  ledger_rows:ledger.length, source_rows:source.length, matched_refs:matchedRefs.length,
  findings:findings.length, by_type:JSON.stringify(byType),
  variance_total:variance.toFixed(2),
  material_count:findings.filter((f)=>f.amount_impact>=run.materiality).length,
  started_at:run.started_at, completed_at:new Date().toISOString().slice(0,19)+'Z', status:'complete',
};
return [{json:{summary,findings}}];

